    /// `fprintf`'s outcome: `ret`, its return, as a count, or, when negative, the failure that
    /// `err`, the `errno` it left after it was cleared, reports. An `err` of `0` is a failure
    /// that set no `errno`.
    fn outcome(ret: c_int, err: c_int) -> io::Result<usize> {
